    if (!e)
      return out;
    const qty = numOf(e.fields.qty, 1);
    if (level >= 2 && qty !== 1)
      out.qty = qty;
    if (level >= 3 && typeof e.fields.condition === "number")
      out.condition = e.fields.condition;
    if (level >= 3 && strOf(e.fields.slot) && !lent.has(id))
      out.slot = strOf(e.fields.slot).replace(/_/g, " ");
