  maps: {},
  rules: {
    r_small_craft_advisory: {
      id: "r_small_craft_advisory",
      on: { at: "clock >= 13800" },
      do: [
        { type: "weather.set", args: { region: "region_lakeshore_county", state: "gale", minutes: 1200 } },
        { type: "story.flag", args: { name: "small_craft_advisory", value: true } },
        { type: "space.set_route", args: { route: "rt_marina_gull", open: false } },
        { type: "story.flag", args: { name: "ferry_running", value: false } }
      ],
      once: true,
      interrupt: true,
      beat: { hint: "The flags at the marina snap straight out, and Dale starts doubling every dock line." }
    },
    r_small_craft_advisory_ends: {
      id: "r_small_craft_advisory_ends",
      on: { at: "clock >= 15000" },
      do: [
        { type: "story.flag", args: { name: "small_craft_advisory", value: false } },
        { type: "story.flag", args: { name: "ferry_running", value: true } },
        { type: "space.set_route", args: { route: "rt_marina_gull", open: true } }
      ],
      once: true
    },
    r_harbor_fest: {
      id: "r_harbor_fest",
      on: { at: "clock >= 17880" },
      do: [
        { type: "castlife.override", args: { who: "marcus_delgado", place: "lakefront_park", minutes: 180 } },
        { type: "castlife.override", args: { who: "danny_okafor", place: "lakefront_park", minutes: 180 } },
        { type: "castlife.override", args: { who: "priya_nair", place: "lakefront_park", minutes: 180 } },
        { type: "castlife.override", args: { who: "jess_kowalczyk", place: "lakefront_park", minutes: 180 } },
        { type: "castlife.override", args: { who: "dale_whitcomb", place: "lakefront_park", minutes: 180 } },
        { type: "castlife.override", args: { who: "helen_kowalczyk", place: "lakefront_park", minutes: 180 } },
        { type: "castlife.override", args: { who: "nora_whitfield", place: "lakefront_park", minutes: 180 } },
        { type: "set", args: { entity: "pov", field: "scene", value: "conversation" } }
      ],
      once: true,
      interrupt: true,
      beat: { hint: "Smoke from the grill, a brass band warming up, and Priya running past with a walkie-talkie." }
    },
    r_danny_jealous: {
      id: "r_danny_jealous",
      on: { tick: "day" },
      do: [
        {
          type: "relationships.adjust",
          args: { from: "danny_okafor", to: "pov", axis: "warmth", delta: -10, why: "Danny cools toward the player." }
        },
        { type: "note", args: { text: "Danny stops sharing his shortcuts and finds reasons to be on the other side of the shop." } }
      ],
      when: "regard('marcus_delgado', 'pov', 'respect') >= 40",
      cooldownMinutes: 10080,
      beat: { hint: "Danny slides the right-sized socket just out of reach and says it must have gone missing." }
    },
    r_pontoon_overdue: {
      id: "r_pontoon_overdue",
      on: { tick: "slot" },
      do: [
        { type: "signal", args: { class: "overdue", text: "The loan is overdue.", entity: "marina_pontoon" } },
        {
          type: "relationships.adjust",
          args: { from: "dale_whitcomb", to: "pov", axis: "trust", delta: -10, why: "Dale loses a little trust." }
        }
      ],
      when: "flag('pontoon_loaned') and clock > 9720 and not at('marina_pontoon', 'alder_harbor_marina')",
      once: true,
      interrupt: true,
      beat: { hint: "Your phone buzzes: three texts from Dale in a row, each shorter than the last." }
    },
    r_oil_change_due: {
      id: "r_oil_change_due",
      on: { tick: "day" },
      do: [{ type: "note", args: { text: "The oil-change reminder comes on, and Marcus offers a friendly employee discount on parts." } }],
      when: "field('pov_truck', 'odometer_mi') - field('pov_truck', 'last_service') >= 7500",
      cooldownMinutes: 10080
    },
    r_pontoon_out: {
      id: "r_pontoon_out",
      on: { tick: "slot" },
      do: [{ type: "story.flag", args: { name: "pontoon_out", value: true } }],
      when: "stage('q_pontoon_weekend') == 'loan' and not at('marina_pontoon', 'alder_harbor_marina')",
      once: true
    }
  },
