    inputSchema: object({ chatId: CHAT_ID3, target: { type: "object", description: "How far to skip." }, overrides: { type: "object", description: "Interrupt classes to stop, note or ignore for this skip." }, text: { type: "string", description: "The player's words for it." } }, ["chatId", "target"]),
